const assert = require('node:assert/strict');
const test = require('node:test');
const { run } = require('./app');

for (const action of ['find', 'cancel', 'archive']) {
  test(`${action}: shared identifier contract`, () => {
    const expected = { find: 'open', cancel: 'cancelled', archive: 'archived' };
    for (const id of ['A1', ' A1 ', '\tA1\n', '\u00a0A1\u00a0']) {
      assert.deepEqual(run({ action, id }), { id: 'A1', status: expected[action] });
    }
    for (const id of [undefined, null, 1, false, {}, [], '', ' \t\n', new String('A1')]) {
      assert.throws(() => run({ action, id }), /invalid id/);
    }
    for (const id of ['unknown', ' a1 ', 'A 1']) {
      if (action === 'find') assert.equal(run({ action, id }), null);
      else assert.throws(() => run({ action, id }), /^Error: missing$/);
    }
  });
}

